INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass Ladungssicherung in Containern immer automatisch erfolgt?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle oder halbautomatische Sicherung nötig"}, {"text": "Ja", "correct": false, "because": "Erfordert aktive Maßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt vor Diebstahl bei Containern?', 3, '[{"text": "Plombierung", "correct": true, "because": "Verhindert unbefugtes Öffnen"}, {"text": "Farbcodierung", "correct": false, "because": "Nur visuelle Markierung"}, {"text": "Stapelhöhe", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzmaßnahmen sind für Containertransporte wichtig?', 5, '[{"text": "Ladungssicherung", "correct": true, "because": "Verhindert Verrutschen"}, {"text": "Begasungskontrolle", "correct": true, "because": "Schützt vor Gesundheitsrisiken"}, {"text": "GPS-Tracking", "correct": true, "because": "Verfolgt Standort"}, {"text": "Farbgestaltung", "correct": false, "because": "Kosmetisch"}, {"text": "Marketing", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Trockenmittel schützen vor Feuchtigkeit. b) Sie verhindern Diebstahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Diebstahlschutz anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Sicherung von Containern?', 4, '[{"text": "Verplombung", "correct": false, "because": "Schützt vor Zugriff"}, {"text": "Gewichtsverteilung", "correct": false, "because": "Sichert Stabilität"}, {"text": "Containermarke", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob begaste Container immer gekennzeichnet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Markierungen können fehlen"}, {"text": "Ja", "correct": false, "because": "Nicht immer vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt vor Gesundheitsrisiken bei begasten Containern?', 4, '[{"text": "Gasfreimessung", "correct": true, "because": "Prüft Schadstoffe"}, {"text": "Schnelles Öffnen", "correct": false, "because": "Erhöht Risiko"}, {"text": "Manuelle Lüftung", "correct": false, "because": "Zu unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Twistlocks für alle Containertransporte ausreichen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Zusätzliche Sicherungen nötig"}, {"text": "Ja", "correct": false, "because": "Nicht immer ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt eine CSC-Plakette vor Diebstahl?', 2, '[{"text": "Nein", "correct": true, "because": "Prüft Sicherheitsstandards"}, {"text": "Ja", "correct": false, "because": "Kein Diebstahlschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hilfsmittel sichern die Ladung in Containern?', 5, '[{"text": "Luftsäcke", "correct": true, "because": "Füllen Freiräume"}, {"text": "Laschaugen", "correct": true, "because": "Fixieren Ladung"}, {"text": "Holzbalken", "correct": true, "because": "Verteilen Gewicht"}, {"text": "Papierpolster", "correct": false, "because": "Zu schwach"}, {"text": "Farbmarkierungen", "correct": false, "because": "Kein Sicherungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Sicherung eines Containers?', 4, '[{"text": "Gewichtsverteilung", "correct": true, "because": "Verhindert Kippen"}, {"text": "Schnelles Beladen", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Optisches Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verplombung schützt vor unbefugtem Zugriff. b) Sie verhindert Feuchtigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Feuchtigkeit anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Schutz eines Containers?', 3, '[{"text": "Trockenmittel", "correct": false, "because": "Schützt vor Feuchtigkeit"}, {"text": "Laschbänder", "correct": false, "because": "Sichern Ladung"}, {"text": "Werbeaufkleber", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Gesundheitsrisiken bei Containern minimiere?', 4, '[{"text": "Atemschutz und Gasfreimessung", "correct": true, "because": "Schützt vor Begasung"}, {"text": "Schnelles Öffnen", "correct": false, "because": "Erhöht Risiko"}, {"text": "Ohne Kontrolle", "correct": false, "because": "Gefährlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Container immer feuchtigkeitsfrei sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Feuchtigkeit durch Schwitzwasser"}, {"text": "Ja", "correct": false, "because": "Trockenmittel oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel schützt vor Schwitzwasserschäden?', 4, '[{"text": "Trockenmittel", "correct": true, "because": "Bindet Feuchtigkeit"}, {"text": "Papierpolster", "correct": false, "because": "Kein Feuchtigkeitsschutz"}, {"text": "Plastikfolie", "correct": false, "because": "Begrenzt wirksam"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind alle Container automatisch sicher?', 2, '[{"text": "Nein", "correct": true, "because": "Erfordern Schutzmaßnahmen"}, {"text": "Ja", "correct": false, "because": "Sicherung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern Container auf Schiffen?', 5, '[{"text": "Twistlocks", "correct": true, "because": "Fixieren Container"}, {"text": "Laschings", "correct": true, "because": "Verhindern Kippen"}, {"text": "Cellguides", "correct": true, "because": "Führen Container"}, {"text": "Farbmarkierungen", "correct": false, "because": "Kein Sicherungsfaktor"}, {"text": "Papierstreifen", "correct": false, "because": "Zu schwach"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Containerbeladung unwichtig?', 3, '[{"text": "Gewichtsverteilung", "correct": false, "because": "Sichert Stabilität"}, {"text": "Laschpunkte", "correct": false, "because": "Fixieren Ladung"}, {"text": "Containermarke", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich einen Container sichere?', 4, '[{"text": "Ladung fixieren, Gewicht verteilen, plombieren", "correct": true, "because": "Umfassender Schutz"}, {"text": "Nur stapeln", "correct": false, "because": "Fehlt Sicherung"}, {"text": "Ohne Kontrolle beladen", "correct": false, "because": "Riskant"}]');
